}

Method.Source:
/// <summary>
///  AVA/WEN 2024/03/05
/// </summary>
/// <param name = "_prodParmReportFinished">ProdParmReportFinished</param>
/// <param name = "_common">Common</param>
/// <param name = "_prodTable">ProdTable</param>
protected void initializeProdParmReportFinish(ProdParmReportFinished _prodParmReportFinished, Common _common, ProdTable _prodTable)
{
    if (_common.TableId == tableNum(AVATraverseTrans))
    {
        travTrans = _common;
        _prodTable = ProdTable::find(travTrans.ProdId);
        _prodParmReportFinished.initFromProdTable(_prodTable);
        //_prodParmReportFinished.QtyGood          = 0;
        _prodParmReportFinished.QtyError         = 0;
        _prodParmReportFinished.ErrorCause       = ProdErrorCause::None;
        _prodParmReportFinished.ReportFinishProd = NoYes::Yes;
        _prodParmReportFinished.QtyGood          = travTrans.Qty;             
        _prodParmReportFinished.AVATraverseNum   = travTrans.TravNum;
        InventDim   inventDim = inventDim::find(_prodParmReportFinished.InventDimId);
        inventDim.inventBatchId = travTrans.InventBatchId;
        inventDim = InventDim::findOrCreate(inventDim);
        _prodParmReportFinished.InventDimId = inventDim.inventDimId;        
    }
    next initializeProdParmReportFinish(_prodParmReportFinished, _common, _prodTable);

    _prodParmReportFinished.BOMAutoConsump = BOMAutoConsump::Never; //N.Freidenberger 26.07.2024
    _prodParmReportFinished.AcceptError    = NoYes::Yes;

    /*if (_common.TableId == tableNum(ProdTable))
    {
        AVATraverseTrans travTrans = AVATraverseTrans::findByProdId(_prodTable.ProdId);
        _prodParmReportFinished.QtyGood = travTrans.Qty;
        InventDim   inventDim = inventDim::find(_prodParmReportFinished.InventDimId);
        inventDim.inventBatchId = travTrans.InventBatchId;
        inventDim = InventDim::findOrCreate(inventDim);
        _prodParmReportFinished.InventDimId = inventDim.inventDimId;
    }*/
}

/// <summary>
/// designed N.Wert
/// </summary>
/// <param name = "_common">_common</param>
/// <param name = "_prodParmReportFinished">_prodParmReportFinished</param>
void insert(Common  _common, ParmBuffer  _prodParmReportFinished)
{
    if (_common.TableId == tableNum(AVATraverseTrans))
    {
        travTrans = _common;
    }
    next insert(_common, _prodParmReportFinished);
}
